DO $$ BEGIN IF current_database()<>'membros_test' THEN RAISE EXCEPTION 'Banco de teste obrigatório'; END IF; END $$;
SELECT public.testar(NOT has_table_privilege('authenticated','public.membros_teste_progresso','SELECT'),'progresso de teste não é tabela pública');
SELECT public.testar(NOT has_function_privilege('authenticated','public.membros_direitos_membro(uuid,uuid)','execute'),'direitos internos não expõem outra identidade');
SELECT public.testar(NOT has_function_privilege('anon','public.membros_biblioteca(boolean,boolean)','execute'),'anônimo não abre biblioteca');
SET ROLE authenticated;
SELECT set_config('request.jwt.claim.role','authenticated',false);
SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000004',false);
SELECT public.testar(public.recusa('select public.membros_biblioteca(true,false)'),'cliente não inicia teste de admin');
SELECT public.testar(public.recusa('select public.membros_teste_reiniciar()'),'cliente não apaga progresso de teste');
SELECT public.testar(public.recusa('select public.membros_teste_materiais(''30000000-0000-0000-0000-000000000001'')'),'cliente não lê teste alheio');
SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',false);
SELECT public.testar(jsonb_array_length(public.membros_biblioteca(true,false)->'produtos')=2,'teste esconde rascunhos de administrador');
SELECT public.testar((SELECT p->'origens'='[]'::jsonb AND (p->>'progresso')::int=0 FROM jsonb_array_elements(public.membros_biblioteca(true,false)->'produtos') p WHERE p->>'id'='30000000-0000-0000-0000-000000000001'),'teste de admin sem concessão fica bloqueado');
SELECT public.testar(public.recusa('select public.membros_teste_materiais(''30000000-0000-0000-0000-000000000001'')'),'admin sem concessão não lê conteúdo no teste');
SELECT public.testar(public.recusa('select public.membros_teste_salvar_progresso(''40000000-0000-0000-0000-000000000001'',10,60,false)'),'admin sem concessão não grava progresso de teste');
INSERT INTO public.membros_acessos(user_id,produto_id,origem,referencia) VALUES(auth.uid(),'30000000-0000-0000-0000-000000000001','manual','teste-administrador');
SELECT public.testar(jsonb_array_length(public.membros_teste_materiais('30000000-0000-0000-0000-000000000001')->'materiais')=2,'manual real libera o teste');
SELECT public.testar(public.recusa('select public.membros_teste_materiais(''30000000-0000-0000-0000-000000000001'',true)'),'bloqueio simulado é conferido no servidor');
SELECT public.testar(public.recusa('select public.membros_teste_salvar_progresso(''40000000-0000-0000-0000-000000000001'',20,60,true,true)'),'bloqueio impede gravação por chamada direta');
SELECT public.membros_teste_salvar_progresso('40000000-0000-0000-0000-000000000001',20,60,false);
SELECT public.testar((public.membros_teste_materiais('30000000-0000-0000-0000-000000000001')->'progresso'->0->>'posicao')::numeric=20,'posição do vídeo pode ser retomada');
SELECT public.testar((SELECT count(*) FROM public.membros_progresso)=0,'teste não escreve progresso verdadeiro do administrador');
SELECT public.membros_teste_salvar_progresso('40000000-0000-0000-0000-000000000001',60,60,true);
SELECT public.testar((public.membros_biblioteca(true,false)->'jornada'->>'concluidos')::int=1,'conquista vem de conclusão persistida');
SELECT public.testar((public.membros_biblioteca(true,true)->'jornada'->>'concluidos')::int=0,'bloqueado não revela progresso ou conquista');
SELECT public.testar((SELECT bool_and(p->'origens'='[]'::jsonb) FROM jsonb_array_elements(public.membros_biblioteca(true,true)->'produtos') p),'bloqueio inclui conteúdos gratuitos');
SELECT public.testar(public.membros_teste_reiniciar()=1,'reinício apaga somente progresso de teste próprio');
SELECT public.testar((public.membros_biblioteca(true,false)->'jornada'->>'concluidos')::int=0,'reinício remove conquista do teste');
SELECT public.testar(public.membros_admin(),'papel de administrador permanece intacto');
SELECT public.testar(EXISTS(SELECT 1 FROM public.membros_acessos WHERE user_id=auth.uid() AND referencia='teste-administrador' AND revogado_em IS NULL),'reinício e bloqueio preservam concessão manual');
SELECT public.testar((SELECT count(*)=3 FROM jsonb_array_elements(public.membros_biblioteca(false,false)->'produtos')),'modo administrativo normal continua disponível');
SELECT public.testar(NOT public.membros_pagamentos_habilitados(),'Kiwify e Asaas permanecem desligados');
RESET ROLE;
SELECT public.testar(EXISTS(SELECT 1 FROM public.membros_progresso WHERE user_id='00000000-0000-0000-0000-000000000002' AND concluido),'progresso do comprador não foi alterado pelo teste');
